from pathlib import Path
root=Path(__file__).parent/'public/art'
root.mkdir(parents=True,exist_ok=True)
pre='<svg xmlns="http://www.w3.org/2000/svg" width="800" height="700" viewBox="0 0 800 700"><g stroke-linecap="round" stroke-linejoin="round">'
end='</g></svg>'
def write(name,s): (root/f'{name}.svg').write_text(pre+s+end)
